var line = Console.ReadLine() ?? "";
if (line.Length == 0) Environment.Exit(1);
var segments = line.Split('.');
foreach (var segment in segments)
{
    if (segment.Length == 0) Environment.Exit(1);
}
if (segments.Length == 1)
{
    Console.WriteLine("global " + line);
    return;
}
var namespacePart = string.Join('.', segments[..^1]);
Console.WriteLine(namespacePart + " " + segments[^1]);

if (!int.TryParse(Console.ReadLine(), out var count) || count < 0 || count > 1000) Environment.Exit(1);
long total = 0;
for (var i = 0; i < count; i++)
{
    var tokens = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
    if (tokens.Length != 3) Environment.Exit(1);
    if (!int.TryParse(tokens[2], out var score) || score < 0 || score > 100) Environment.Exit(1);
    var employee = Employee.Create(tokens[0], tokens[1], score);
    if (employee is null) Environment.Exit(1);
    total += employee.WeightedScore();
}
Console.WriteLine(total);

enum Role
{
    Ops = 1,
    Qa = 2,
    Dev = 3
}

class Employee
{
    private readonly Role _role;
    private readonly int _score;

    private Employee(Role role, int score)
    {
        _role = role;
        _score = score;
    }

    public static Employee? Create(string name, string roleText, int score)
    {
        Role? role = roleText switch
        {
            "dev" => Role.Dev,
            "qa" => Role.Qa,
            "ops" => Role.Ops,
            _ => null
        };
        return role is null ? null : new Employee(role.Value, score);
    }

    public long WeightedScore() => (long)_score * (int)_role;
}
